def label(key):
 if key in LABELS: return LABELS[key]
 prefixes={'cold':'清理L2缓存后的','hot':'未清理L2缓存对照的','control':'未清理L2缓存对照的','a_core_span_cuda':'Attention事件跨度','e_core_span_cuda':'专家计算事件跨度','dispatch_span_cuda':'发给专家的通信事件跨度','combine_span_cuda':'取回并合并结果的通信事件跨度','comm_span_cuda':'通信合计事件跨度','e_w13_nested_span_cuda':'专家第一组矩阵乘事件跨度','e_activation_nested_span_cuda':'专家激活函数事件跨度','e_w2_nested_span_cuda':'专家第二组矩阵乘事件跨度','e_nested_subcall_sum_cuda':'专家子调用合计事件跨度','e_outer_minus_nested_cuda':'专家外层与子调用差额','a_e_comm_sum_cuda':'计算与通信合计事件跨度','serial_span_cuda':'串行总事件跨度','pipeline_cpu_wall':'CPU流程总耗时','dispatch_cpu_submit':'发给专家的CPU提交耗时','dispatch_hook_cpu':'发给专家的CPU接收钩子耗时','combine_cpu_submit':'合并结果的CPU提交耗时','combine_hook_cpu':'合并结果的CPU接收钩子耗时'}
 for suffix,stat in [('_mean_ms','平均值'),('_median_ms','中位数'),('_p99_ms','第99百分位')]:
  if key.endswith(suffix):
   prefix=key[:-len(suffix)]
   if prefix.endswith('_ms'): prefix=prefix[:-3]
   if prefix in prefixes:return prefixes[prefix]+stat+'（毫秒）'
 return key

